#ifdef __CAN_FD__ //kjh_190706s
void ChannelControl(int index)
{ //kjg_190323
	int	ch;//kjh_220321, group, scan_ch;

	ch = index;

	myCh = &(myData->cData[ch]);
	if(set_testCond_point(ch) < 0) return;

	cState_Operation(ch);
	cIO_State_Check(ch);

	cFaultCond_Check(ch);

	if(myData->ChAttribute[ch].chNo_master == 0) return;

	if(myCh->op.state != C_RUN) return;
	if(myCh->op.phase != P50) return;
	if(myCh->misc.active_division != ACTIVE_DIV_NONE) return;

	cStopCond(ch);
	if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
		cActiveDivision(ch);
		return;
	}

	cEndCond(ch);
	if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
		if(myCh->misc.active_division == ACTIVE_DIV_TEST_COND_UPDATE1
			|| myCh->misc.active_division
			== ACTIVE_DIV_TEST_COND_UPDATE2) { //kjg_170810
			cActiveDivision(ch);
		} else {
			cFaultCond_Soft2(ch);
			cActiveDivision(ch);
		}
		return;
	}

	cEndCond_Aux(ch);
	if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
		cFaultCond_Soft2(ch);
		cActiveDivision(ch);
		return;
	}

	cEndCond_Can(ch);
	if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
		cFaultCond_Soft2(ch);
		cActiveDivision(ch);
		return;
	}

	if(myCh->op.stepType == STEP_CYCLE
		|| myCh->op.stepType == STEP_LOOP) return;

	cUserControl(ch);
	cSaveCond(ch);
}
#else //CAN_2p0b

void ChannelControl(int index)
{
	int	ch, start, end;//kjh_211021 group, scan_ch;

	if(index < 4) {
		start = 0;
		if(myPs->config.installedCh < 4) {
			end = myPs->config.installedCh;
		} else {
			end = 4;
		}
	} else if(index < 8) {
		start = 4;
		if(myPs->config.installedCh < 8) {
			end = myPs->config.installedCh;
		} else {
			end = 8;
		}
	} else if(index < 12) {
		start = 8;
		if(myPs->config.installedCh < 12) {
			end = myPs->config.installedCh;
		} else {
			end = 12;
		}
	} else if(index < 16) {
		start = 12;
		if(myPs->config.installedCh < 16) {
			end = myPs->config.installedCh;
		} else {
			end = 16;
		}
	} else if(index < 20) {
		start = 16;
		if(myPs->config.installedCh < 20) {
			end = myPs->config.installedCh;
		} else {
			end = 20;
		}
	} else if(index < 24) {
		start = 20;
		if(myPs->config.installedCh < 24) {
			end = myPs->config.installedCh;
		} else {
			end = 24;
		}
	} else if(index < 28) {
		start = 24;
		if(myPs->config.installedCh < 28) {
			end = myPs->config.installedCh;
		} else {
			end = 28;
		}
	} else { //32
		start = 28;
		if(myPs->config.installedCh < 32) {
			end = myPs->config.installedCh;
		} else {
			end = 32;
		}
	}

	index = index % 4;

	switch(index) {
		case 0:
			for(ch=start; ch < end; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				cState_Operation(ch);
				cIO_State_Check(ch);
			}
			break;
		case 1:
			for(ch=start; ch < end; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				cFaultCond_Check(ch);
			}
			break;
		case 2:
			for(ch=start; ch < end; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				if(myData->ChAttribute[ch].chNo_master == 0) continue;

				if(myCh->op.state != C_RUN) continue;
				if(myCh->op.phase != P50) continue;
				if(myCh->misc.active_division != ACTIVE_DIV_NONE) continue;

				cStopCond(ch);
				if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
					cActiveDivision(ch);
					continue;
				}

				cEndCond(ch);
				if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
					if(myCh->misc.active_division
						== ACTIVE_DIV_TEST_COND_UPDATE1
						|| myCh->misc.active_division
						== ACTIVE_DIV_TEST_COND_UPDATE2) { //kjg_170810
						cActiveDivision(ch);
					} else {
						cFaultCond_Soft2(ch);
						cActiveDivision(ch);
					}
					continue;
				}

				cEndCond_Aux(ch);
				if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
					cFaultCond_Soft2(ch);
					cActiveDivision(ch);
					continue;
				}

				cEndCond_Can(ch);
				if(myCh->misc.active_division != ACTIVE_DIV_NONE) {
					cFaultCond_Soft2(ch);
					cActiveDivision(ch);
					continue;
				}
			}
			break;
		case 3:
			for(ch=start; ch < end; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				if(myData->ChAttribute[ch].chNo_master == 0) continue;

				if(myCh->op.state != C_RUN) continue;
				if(myCh->op.phase != P50) continue;
				if(myCh->op.stepType == STEP_CYCLE
					|| myCh->op.stepType == STEP_LOOP) continue;
				if(myCh->misc.active_division != ACTIVE_DIV_NONE) continue;

				cUserControl(ch);
				cSaveCond(ch);
			}
			break;
		default: break;
	}
}
#endif

void cState_Operation(int ch)
{
	switch(myCh->op.state) {
		case C_IDLE: 	cIdle(ch);		break;
		case C_STANDBY:	cStandby(ch);	break;
		case C_RUN:		cRun(ch);		break;
		case C_PAUSE:	cPause(ch);		break;
		case C_CALI: 	cCali(ch);		break;
		case C_FAULT:	cFault(ch);		break;
		default: break;
	}
}

void cIdle(int ch)
{
	switch(myData->AppControl.config.systemModel) {
		case C_KATECH_20V_1000A_500A_100A:
		case C_LGC_50V_40A_10A_4A: //kjg_120209
		case C_LGC_50V_40A_10A_4A_2:
		case C_LGC_50V_40A_10A_4A_3:
		case C_LGC_50V_40A_10A_4A_4:
		case C_SDI_70V_50A_5A_4KW:
		case C_SDI_70V_50A_5A_4KW_2:
		case C_SDI_70V_50A_5A_7KW:
		case C_SDI_70V_50A_5A_7KW_2:
		case C_SDI_70V_250A_25A_18KW:
		case C_SDI_80V_50A_25A_10A:		//csk_130418
		case C_SDI_80V_50A_25A_10A_2:
		case C_SDI_80V_50A_25A_10A_3:
		case C_SDI_80V_50A_25A_10A_4:
		case C_KATECH_100V_30A_15A_5A: //csk_131129
		case C_SBL_150V_250A_10A_38KW: //lki_111010
		case C_SBL_150V_250A_10A_75KW_4:
		case C_SBL_150V_250A_10A_75KW_5:
			if(ch < 4) {
				myCh->op.state = C_STANDBY;
				myCh->op.phase = P0;
			}
			break;
		default:
			if(ch < myPs->config.installedCh) { //kjg_120626
				myCh->op.state = C_STANDBY;
				myCh->op.phase = P0;
			}
			break;
	}
}

