void cStandby_sig_cable_check_11(int ch)
{
	int toPs1, fail_flag, group;
	long val, vp_upper, vp_lower, vs_upper, vs_lower;
	unsigned long set_time;
	S_MSG_VAL SendMsg;

	group = 0;
	fail_flag = 0;
	//kjh_211021 set_time = 50; //10ms * 50 = 500ms
	set_time = 500; //500ms	//kjh_211021
	//vp_upper = 5000000; //5V
	//vp_lower = -500000; //-0.5V
	//kjg_120225
	vp_upper = myPs->config.maxV[0] / 10; //10%
	vp_lower = (-vp_upper) / 10; //-1%
	vs_upper = myPs->config.maxV[0] / 500; //0.2%
	vs_lower = (-vs_upper); //-0.2%

	switch(myCh->signal[C_SIG_CABLE_CHECK]) {
		case P0: //SR_OPEN
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P1: //SR_OPEN
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->misc.Vpower > vp_upper
					|| myCh->misc.Vpower < vp_lower) {
					fail_flag = 1;
				}
				if(myCh->op.Vsens > (myPs->config.maxV[0] + vs_upper)
					|| myCh->op.Vsens < vs_lower) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > vs_upper || val < vs_lower) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK]++;
				}
			}
			break;
		case P2: //SR_CLOSE
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P3: //SR_CLOSE
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->op.Vsens > (myPs->config.maxV[0] + vs_upper)
					|| myCh->op.Vsens < vs_lower) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > vs_upper || val < vs_lower) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK] = P10;
					myCh->signal[C_SIG_CMD_RUN] = P2;
				}
			}
			break;
		case P10: //SR_CLOSE
			break;
		default:
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK] = P0;
			myCh->signal[C_SIG_CMD_RUN] = P0;

			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_MODULE_COA_TROUBLE_CODE;
			SendMsg.val[0] = M_CD_FAULT_LOAD_LINE2;
			SendMsg.val[2] = ch+1;
			toPs1 = MODULE_TO_COA1;
			send_msg(toPs1, (char *)&SendMsg);
			break;
	}
}

void cStandby_sig_cable_check_12(int ch)
{
	int toPs1, fail_flag, group;
	long val, vp_upper=0, vp_lower=0;
	long vs_upper=0, vs_lower=0, comp_v=0; //kjh_211021
	unsigned long set_time;
	S_MSG_VAL SendMsg;

	group = 0;
	fail_flag = 0;
	set_time = 500; //500ms

	if(myPs->config.ratioV == MICRO_UNIT) { //uV //kjh_211021s
		vp_upper = 5000000; //5V
		vp_lower = -500000; //-0.5V
		vs_upper = myPs->config.maxV[0]; //100%	//kjh_211021
		vs_lower = -100000; //0.1v	//kjh_211021
		comp_v = 70000;	//kjh_211021
	} else if(myPs->config.ratioV == MILLI_UNIT) { //mV
		vp_upper = 5000; //5V
		vp_lower = -500; //-0.5V
		vs_upper = myPs->config.maxV[0]; //100% //kjh_211021
		vs_lower = -100; //-0.1v	//kjh_211021
		comp_v = 70; //0.070V	//kjh_211021
	}	//kjh_211021e

	switch(myCh->signal[C_SIG_CABLE_CHECK]) {
		case P0:
			myCh->misc.ch_output_state |= 0x04; //pack_relay_on
			myCh->misc.tmp_ch_output_state = myCh->misc.ch_output_state;
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P1:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * myPs->config.scan_period)
				>= myData->canTransmitSetData.commonData[ch][0].value[1]) {
				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_CABLE_CHECK]++;
				Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
				Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
			}
			break;
		case P2:
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->misc.Vpower > vp_upper
					|| myCh->misc.Vpower < vp_lower) {
					fail_flag = 1;
				}
				if(myCh->op.Vsens > vs_upper || myCh->op.Vsens < (vs_lower)) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > comp_v || val < (-comp_v)) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK]++;
				}
			}
			break;
		case P4:
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF); //SR_CLOSE
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF); //SR_CLOSE
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P5:
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->op.Vsens > vs_upper || myCh->op.Vsens < (vs_lower)) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > comp_v || val < (-comp_v)) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK] = P10;
					myCh->signal[C_SIG_CMD_RUN] = P2;
				}
			}
			break;
		case P10: //SR_CLOSE
			break;
		default:
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF); //SR_CLOSE
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF); //SR_CLOSE
			myCh->misc.ch_output_state &= ~(0x04); //pack_relay_off
			myCh->misc.tmp_ch_output_state = myCh->misc.ch_output_state;
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK] = P0;
			myCh->signal[C_SIG_CMD_RUN] = P0;

			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_MODULE_COA_TROUBLE_CODE;
			SendMsg.val[0] = M_CD_FAULT_LOAD_LINE2;
			SendMsg.val[2] = ch+1;
			toPs1 = MODULE_TO_COA1;
			send_msg(toPs1, (char *)&SendMsg);
			break;
	}
}

