			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK] = P0;
			myCh->signal[C_SIG_CMD_RUN] = P0;

			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
