void cStandby_sig_cable_check_21(int ch)
{ //lki_111010
	int toPs1, fail_flag, group;
	long val, vp_upper=0, vp_lower=0, diff_upper=0, diff_lower=0;
	unsigned long set_time;
	S_MSG_VAL SendMsg;

	group = 0;
	fail_flag = 0;
	set_time = 500; //500ms

	if(myPs->config.ratioV == MICRO_UNIT) { //uV //kjh_211021s
		diff_upper = (myPs->config.maxV[0] * 5 / 1000); // 0.5% of maxV[0]
		diff_lower = (-diff_upper);
		vp_upper = 5000000; //5V
		vp_lower = diff_lower;
	} else if(myPs->config.ratioV == MILLI_UNIT) { //mV
		diff_upper = (myPs->config.maxV[0] * 5 / 1000); // 0.5% of maxV[0]
		diff_lower = (-diff_upper);
		vp_upper = 5000; //5V
		vp_lower = diff_lower;
	}

	switch(myCh->signal[C_SIG_CABLE_CHECK]) {
		case P0: //SR_OPEN
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P1: //SR_OPEN
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->misc.Vpower < vp_lower){
					fail_flag = 1;
				}
				if(myCh->op.Vsens > myData->mData.config.maxV[0]
					|| myCh->op.Vsens < vp_lower) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > diff_upper || val < diff_lower) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK]++;
				}
			}
			break;
		case P2: //SR_OPEN
			if(myCh->misc.Vpower > vp_upper) {
				myCh->signal[C_SIG_OUT_SWITCH] = P65;
				myCh->signal[C_SIG_SEMI_SWITCH] = P0;
				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_CABLE_CHECK]++;
			} else {
				myCh->signal[C_SIG_CABLE_CHECK] = P4;

			}
			break;
		case P3: //SR_OPEN
			myCh->misc.tmpDelayTime++;
			if(myCh->signal[C_SIG_OUT_SWITCH] == P66) {
				if(myCh->misc.Vpower > vp_upper) {
					fail_flag = 1;
				}

				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK]++;
				}
			}
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) > 10000) {  //10s
				myCh->signal[C_SIG_CABLE_CHECK] = P11;
			}
			break;
		case P4: //SR_CLOSE
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P5: //SR_CLOSE
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->op.Vsens > myData->mData.config.maxV[0]
					|| myCh->op.Vsens < vp_lower) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > diff_upper || val < diff_lower) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK] = P10;
					myCh->signal[C_SIG_CMD_RUN] = P2;
				}
			}
			break;
		case P10: //SR_CLOSE
			break;
		default:  //SR_OPEN
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK] = P0;
			myCh->signal[C_SIG_CMD_RUN] = P0;

			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_MODULE_COA_TROUBLE_CODE;
			SendMsg.val[0] = M_CD_FAULT_LOAD_LINE2;
			SendMsg.val[2] = ch+1;
			toPs1 = MODULE_TO_COA1;
			send_msg(toPs1, (char *)&SendMsg);
			break;
	}
}

void cStandby_sig_cable_check_22(int ch)
{ //lki_111120
	int toPs1, fail_flag, group;
	long val, vp_upper=0, vp_lower=0, diff_upper=0, diff_lower=0;
	unsigned long set_time;
	S_MSG_VAL SendMsg;

	group = 0;
	fail_flag = 0;
	set_time = 500; //500ms

	if(myPs->config.ratioV == MICRO_UNIT) { //uV //kjh_211021s
		diff_upper = (myPs->config.maxV[0] * 5 / 1000); // 0.5% of maxV[0]
		diff_lower = (-diff_upper);
		vp_upper = 5000000; //5V
		vp_lower = diff_lower;
	} else if(myPs->config.ratioV == MILLI_UNIT) { //mV
		diff_upper = (myPs->config.maxV[0] * 5 / 1000); // 0.5% of maxV[0]
		diff_lower = (-diff_upper);
		vp_upper = 5000; //5V
		vp_lower = diff_lower;
	}

	switch(myCh->signal[C_SIG_CABLE_CHECK]) {
		case P0:
			myCh->misc.ch_output_state |= 0x04; //pack_relay_on
			myCh->misc.tmp_ch_output_state = myCh->misc.ch_output_state;
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P1:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * myPs->config.scan_period)
				>= myData->canTransmitSetData.commonData[ch][0].value[1]) {
				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_CABLE_CHECK]++;
				Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF); //SR_OPEN
				Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);	//SR_OPEN
			}
			break;
		case P2: //SR_OPEN
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->misc.Vpower < vp_lower){
					fail_flag = 1;
				}
				if(myCh->op.Vsens > myData->mData.config.maxV[0]
					|| myCh->op.Vsens < vp_lower) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > diff_upper || val < diff_lower) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK]++;
				}
			}
			break;
		case P3: //SR_OPEN
			if(myCh->misc.Vpower > vp_upper) {
				myCh->signal[C_SIG_OUT_SWITCH] = P65;
				myCh->signal[C_SIG_SEMI_SWITCH] = P0;
				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_CABLE_CHECK]++;
			} else {
				myCh->signal[C_SIG_CABLE_CHECK] = P5;

			}
			break;
		case P4: //SR_OPEN
			myCh->misc.tmpDelayTime++;
			if(myCh->signal[C_SIG_OUT_SWITCH] == P66) {
				if(myCh->misc.Vpower > vp_upper) {
					fail_flag = 1;
				}

				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK]++;
				}
			}
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) > 10000) {  //10s
				myCh->signal[C_SIG_CABLE_CHECK] = P11;
			}
			break;
		case P5: //SR_CLOSE
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON);
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK]++;
			break;
		case P6: //SR_CLOSE
			myCh->misc.tmpDelayTime++;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period) >= set_time) {
				if(myCh->op.Vsens > myData->mData.config.maxV[0]
					|| myCh->op.Vsens < vp_lower) {
					fail_flag = 1;
				}
				val = myCh->op.Vsens - myCh->misc.Vbus;
				if(val > diff_upper || val < diff_lower) {
					fail_flag = 1;
				}
				myCh->misc.tmpDelayTime = 0;
				if(fail_flag == 1) {
					myCh->signal[C_SIG_CABLE_CHECK] = P11;
				} else {
					myCh->signal[C_SIG_CABLE_CHECK] = P10;
					myCh->signal[C_SIG_CMD_RUN] = P2;
				}
			}
			break;
		case P10: //SR_CLOSE
			break;
		default:  //SR_OPEN
			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF);
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);
			myCh->misc.ch_output_state &= ~(0x04); //pack_relay_off
			myCh->misc.tmp_ch_output_state = myCh->misc.ch_output_state;
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_CABLE_CHECK] = P0;
			myCh->signal[C_SIG_CMD_RUN] = P0;

			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_MODULE_COA_TROUBLE_CODE;
			SendMsg.val[0] = M_CD_FAULT_LOAD_LINE2;
			SendMsg.val[2] = ch+1;
			toPs1 = MODULE_TO_COA1;
			send_msg(toPs1, (char *)&SendMsg);
			break;
	}
}

