				Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF); //SR_OPEN
				Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, OFF);    //SR_OPEN
				//myCh->misc.ch_output_state = 0x01; //key_on
				//myCh->misc.tmp_ch_output_state = myCh->misc.ch_output_state;
