void cRun(int ch)
{
	int range_delay; //jhkw_190629
	int slave_idx, slave_ch, i, j, idx;
	long total_Isens, total_AmpareHour, total_WattHour, total_watt;
	long sum_AmpareHour, sum_WattHour, sum_CycleAmpareHour, sum_CycleWattHour;
	long tmp_total_Isens;
	long l_val;	//kjhw_180913
	double avgV, avgI;

	i = find_master_ch(ch);
	if(i < 0) return;
	if(i != ch && myData->cData[i].op.phase == P0 && myCh->op.phase == P0) {
		return;
	}

	//jhkw_190629s	//if V_RANGE2 delay needs
	range_delay = 0;
	if(myData->testCond[i].reserved.select_run == 0) {
	} else {
		if((myData->cData[i].misc.delay_count1 * myPs->config.scan_period)
			>= range_delay) {
			myData->cData[i].misc.delay_count1 = 0;
		} else {
			if(myData->ChAttribute[ch].chNo_master != 0) { //master
				myData->cData[i].misc.delay_count1++;
			}
			return;
		}
	}	//jhkw_190629e

	time_cal_increment(myCh->op.totalRunTime_day, myCh->op.totalRunTime,
		myPs->misc.increment_period);
	myCh->op.totalRunTime_day = myPs->misc.tmp_inc_time_day;
	myCh->op.totalRunTime = myPs->misc.tmp_inc_time;

	if(myData->ChAttribute[ch].chNo_master != 0) { //master //jhkw_181001
		if(myCh->op.totalRunTime_day == 0 && myCh->op.totalRunTime <= 10) {
			idx = IDX_COM_OBJ_FAULT_UPPER_V;
			l_val = myTestCond->common_object[idx];
			if(l_val == 0) {
				l_val = RANGE1 - 1;
			} else if(l_val <= myData->mData.config.maxV[3]) {
				l_val = RANGE4 - 1;
			} else if(l_val <= myData->mData.config.maxV[2]) {
				l_val = RANGE3 - 1;
			} else if(l_val <= myData->mData.config.maxV[1]) {
				l_val = RANGE2 - 1;
			} else {
				l_val = RANGE1 - 1;
			}

			if((l_val+1) > (long)myData->mData.config.rangeV) {
				l_val = (long)myData->mData.config.rangeV - 1;
			}

			cOutSwitch_Select_rangeV(ch, (int)l_val);
			//return;
		}
	}

	//time_cal_increment(myCh->misc.sum_CycleTime_day,
	//	myCh->misc.sum_CycleTime, myPs->misc.increment_period);
	//myCh->misc.sum_CycleTime_day = myPs->misc.tmp_inc_time_day;
	//myCh->misc.sum_CycleTime = myPs->misc.tmp_inc_time;

	total_Isens = myCh->op.Isens;
	tmp_total_Isens = myCh->misc.tmpIsens;
	total_AmpareHour = myCh->op.charge_AmpareHour
		+ (myCh->op.discharge_AmpareHour * (-1));
	total_WattHour = myCh->op.charge_WattHour
		+ (myCh->op.discharge_WattHour * (-1));
	if(myCh->op.watt >= 0) {
		total_watt = myCh->op.watt;
	} else {
		total_watt = myCh->op.watt * (-1);
	}
	sum_AmpareHour = myCh->op.charge_AmpareHour + myCh->op.discharge_AmpareHour;
	idx = IDX_LOC_OBJ_END_SUM_AMPARE_HOUR_TYPE;
	i = (int)myTestCond->local_object[myCh->elementCycle.cycle_idxStepNo][idx];
	switch(i) {
		case SUM_CHARGE:
			sum_CycleAmpareHour = myCh->op.charge_AmpareHour;
			break;
		case SUM_DISCHARGE:
			sum_CycleAmpareHour = myCh->op.discharge_AmpareHour;
			break;
		default: //SUM_ALL
			sum_CycleAmpareHour = myCh->op.charge_AmpareHour
				+ myCh->op.discharge_AmpareHour;
			break;
	}
	sum_WattHour = myCh->op.charge_WattHour + myCh->op.discharge_WattHour;
	idx = IDX_LOC_OBJ_END_SUM_WATT_HOUR_TYPE;
	j = (int)myTestCond->local_object[myCh->elementCycle.cycle_idxStepNo][idx];
	switch(j) {
		case SUM_CHARGE:
			sum_CycleWattHour = myCh->op.charge_WattHour;
			break;
		case SUM_DISCHARGE:
			sum_CycleWattHour = myCh->op.discharge_WattHour;
			break;
		default: //SUM_ALL
			sum_CycleWattHour = myCh->op.charge_WattHour
				+ myCh->op.discharge_WattHour;
			break;
	}

	for(slave_idx=0; slave_idx < MAX_SLAVE_CH; slave_idx++) {
		slave_ch = (int)myData->ChAttribute[ch].chNo_slave[slave_idx] - 1;
		if(slave_ch >= 0) {
			total_Isens += myData->cData[slave_ch].op.Isens;
			tmp_total_Isens += myData->cData[slave_ch].misc.tmpIsens;
			total_AmpareHour
				+= (myData->cData[slave_ch].op.charge_AmpareHour
				+ (myData->cData[slave_ch].op.discharge_AmpareHour * (-1)));
			total_WattHour
				+= (myData->cData[slave_ch].op.charge_WattHour
				+ (myData->cData[slave_ch].op.discharge_WattHour * (-1)));
			if(myData->cData[slave_ch].op.watt >= 0) {
				total_watt += myData->cData[slave_ch].op.watt;
			} else {
				total_watt += (myData->cData[slave_ch].op.watt * (-1));
			}
			sum_AmpareHour += (myData->cData[slave_ch].op.charge_AmpareHour
				+ myData->cData[slave_ch].op.discharge_AmpareHour);
			sum_WattHour += (myData->cData[slave_ch].op.charge_WattHour
				+ myData->cData[slave_ch].op.discharge_WattHour);
			switch(i) {
				case SUM_CHARGE:
					sum_CycleAmpareHour
						+= myData->cData[slave_ch].op.charge_AmpareHour;
					break;
				case SUM_DISCHARGE:
					sum_CycleAmpareHour
						+= myData->cData[slave_ch].op.discharge_AmpareHour;
					break;
				default: //SUM_ALL
					sum_CycleAmpareHour
						+= (myData->cData[slave_ch].op.charge_AmpareHour
						+ myData->cData[slave_ch].op.discharge_AmpareHour);
					break;
			}
			switch(j) {
				case SUM_CHARGE:
					sum_CycleWattHour
						+= myData->cData[slave_ch].op.charge_WattHour;
					break;
				case SUM_DISCHARGE:
					sum_CycleWattHour
						+= myData->cData[slave_ch].op.discharge_WattHour;
					break;
				default: //SUM_ALL
					sum_CycleWattHour
						+= (myData->cData[slave_ch].op.charge_WattHour
						+ myData->cData[slave_ch].op.discharge_WattHour);
					break;
			}
		}
	}

	myCh->misc.total_tmpIsens = tmp_total_Isens;
	myCh->misc.total_Isens = total_Isens;
	myCh->misc.total_AmpareHour = total_AmpareHour;
	myCh->misc.total_WattHour = total_WattHour;
	myCh->misc.total_watt = total_watt; //kjg_100103_s
	myCh->misc.sum_AmpareHour = sum_AmpareHour;
	myCh->misc.sum_WattHour = sum_WattHour;
	myCh->misc.sum_CycleAmpareHour
		= myCh->misc.seed_CycleAmpareHour + sum_AmpareHour;
	myCh->misc.sum_CycleWattHour
		= myCh->misc.seed_CycleWattHour + sum_WattHour; //kjg_100103_e

	if(myCh->misc.total_Isens > myCh->misc.maxI) {
		myCh->misc.maxI = myCh->misc.total_Isens;
	}
	if(myCh->misc.total_Isens < myCh->misc.minI) {
		myCh->misc.minI = myCh->misc.total_Isens;
	}

	//kjg_111006
	//i = (unsigned char)myCh->misc.tmp_avg_index;
	//myCh->misc.tmpVsens_avg_sum[i] = myCh->misc.tmpVsens;
	//myCh->misc.tmpIsens_avg_sum[i] = tmp_total_Isens;
	i = (unsigned char)myCh->capa.tmp_avg_index;	//jhj_250612	//MAX_STEP_420
	myCh->capa.tmpVsens_avg_sum[i] = myCh->misc.tmpVsens;
	myCh->capa.tmpIsens_avg_sum[i] = tmp_total_Isens;
	i++;
	if(i >= (int)myPs->config.tmp_avg_count) {
		i = 0;
		//myCh->misc.tmp_avg_flag = P1;
		myCh->capa.tmp_avg_flag = P1;	//jhj_250612	//MAX_STEP_450
	}
	//myCh->misc.tmp_avg_index = (unsigned char)i;
	//avgV = myCh->misc.tmpVsens_avg_sum[0];
	//avgI = myCh->misc.tmpIsens_avg_sum[0];
	//if(myCh->misc.tmp_avg_flag == P0) {
	myCh->capa.tmp_avg_index = (unsigned char)i;	//jhj_250612	//MAX_STEP_420
	avgV = myCh->capa.tmpVsens_avg_sum[0];
	avgI = myCh->capa.tmpIsens_avg_sum[0];
	if(myCh->capa.tmp_avg_flag == P0) {
		for(j=1; j < i; j++) {
			//avgV += myCh->misc.tmpVsens_avg_sum[j];
			//avgI += myCh->misc.tmpIsens_avg_sum[j];
			avgV += myCh->capa.tmpVsens_avg_sum[j];	//jhj_250612	//MAX_STEP_420
			avgI += myCh->capa.tmpIsens_avg_sum[j];
		}
		avgV /= (double)j;
		avgI /= (double)j;
	} else {
		for(j=1; j < (int)myPs->config.tmp_avg_count; j++) {
			//avgV += myCh->misc.tmpVsens_avg_sum[j];
			//avgI += myCh->misc.tmpIsens_avg_sum[j];
			avgV += myCh->capa.tmpVsens_avg_sum[j];	//jhj_250612	//MAX_STEP_420
			avgI += myCh->capa.tmpIsens_avg_sum[j];
		}
		avgV /= (double)myPs->config.tmp_avg_count;
		avgI /= (double)myPs->config.tmp_avg_count;
	}
	//myCh->misc.tmpVsens_avg = (long)avgV;
	//myCh->misc.tmpIsens_avg = (long)avgI;
	myCh->capa.tmpVsens_avg = (long)avgV;	//jhj_250612	//MAX_STEP_420
	myCh->capa.tmpIsens_avg = (long)avgI;

	switch(myCh->op.stepType) {
		case STEP_CHARGE:			cStepCharge(ch);		break;
		case STEP_DISCHARGE:		cStepDischarge(ch);		break;
		case STEP_REST:				cStepRest(ch);			break;
		case STEP_LONG_TIME_REST:	cStepLongTimeRest(ch);	break;
		case STEP_OCV:				cStepOcv(ch);			break;
		case STEP_Z:				cStepZ(ch);				break;
		case STEP_PATTERN:			cStepPattern(ch);		break;
		case STEP_EXTERNAL_CAN:		cStepExternalCan(ch);	break;
		case STEP_USERMAP:			cStepUserMap(ch);		break; //kjhw_140828
		case STEP_EXTERNAL_CAN_2:	cStepExternalCan2(ch);	break; //kjg_140916
		default: //STEP_CYCLE, STEP_LOOP, STEP_END
			cStepDefault(ch);
			break;
	}

	Select_OutPoint(0, ch+1, O_CH_RUN_STATE, ON); //kjhw_130702
}

