					myCh->signal[C_SIG_BMS_ACTIVE_PHASE] = P11;
					break;
				case P4: //find
					myCh->signal[C_SIG_BMS_ACTIVE_PHASE] = P41;
					break;
				default: //find
					myCh->signal[C_SIG_BMS_ACTIVE_PHASE] = P41;
