			myCh->misc.saveDt = 0;
			myCh->misc.saveDv = myCh->op.Vsens;
			myCh->misc.saveDi = myCh->op.Isens;
			myCh->misc.saveDtemp = myCh->op.temp;
			myCh->misc.meanSumCount = 0;
			myCh->misc.sum_charge_AmpareHour = 0;
			myCh->misc.seed_charge_AmpareHour = 0;
			myCh->misc.sum_discharge_AmpareHour = 0;
			myCh->misc.seed_discharge_AmpareHour = 0;
			myCh->misc.tmpWatt = 0;
			myCh->misc.sum_charge_WattHour = 0;
			myCh->misc.seed_charge_WattHour = 0;
			myCh->misc.sum_discharge_WattHour = 0;
			myCh->misc.seed_discharge_WattHour = 0;
			myCh->misc.maxV = 0;
			myCh->misc.minV = 0;
			myCh->misc.maxI = 0;
			myCh->misc.minI = 0;
			myCh->misc.cv_maxI = 0;			//ktg_210315s
			myCh->misc.cv_minI = 0;
			myCh->misc.cv_maxI_flag = 0;	
			myCh->misc.cv_minI_flag = 0;	//ktg_210315e
			myCh->misc.waveform_type = 0;
			myCh->misc.cmd_t[0] = 0;
