			myCh->misc.check_fault_delta_AuxV_Time = 0;	//csk_190808
			myCh->signal[C_SIG_SVDF_DETECT_PHASE] = P5;	//ktg_210105
			myCh->signal[C_SIG_DROP_VOLTAGE_PHASE] = P0;	//ktg_210408
			myCh->signal[C_SIG_CAN_SVDF_DETECT_PHASE] = P5;		//ktg_210706
			myCh->signal[C_SIG_CAN_DROP_VOLTAGE_PHASE] = P0;	//ktg_210706
			myCh->signal[C_SIG_GAS_VENTING_DETECT_PHASE] = P0;	//ktg_220331
			myCh->signal[C_SIG_CAN_GAS_VENTING_DETECT_PHASE] = P0;	//ktg_220331
			myCh->signal[C_SIG_ISOLATION_STATE_CHECK] = 0;	//ktg_210908	//ktg_220701
			myCh->signal[C_SIG_CAN_TEST5_RUN] = P0;	//ktg_220724
			myCh->signal[C_SIG_CAN_FREEZE_PHASE] = P0;	//ktg_230728
			myCh->misc2.freeze_Time = 0;
			myCh->misc2.freeze_day = 0;
			myCh->misc.saveTime_count = 0;	//ktg_210411
