			myCh->misc.can_warnning_count = 0;
			myCh->misc.can_error_count = 0;

			myCh->misc.pid_ui1[0] = 0.0;
			myCh->misc.pid_ui1[1] = 0.0;
			myCh->misc.pid_error1[0] = 0.0;
			myCh->misc.pid_error1[1] = 0.0;
			myCh->misc.waveform_type = 0;
			myCh->misc.cmd_t[0] = 0;
			myCh->misc.cmd_t[1] = 0;

			/*myCh->misc.c_v1 = 0;
			myCh->misc.c_v2 = 0;
			myCh->misc.c_t1 = 0;
			myCh->misc.c_t2 = 0;
			myCh->misc.d_count = 0;
			myCh->misc.d_flag = 0;*/
			myCh->capa.c_v1 = 0;	//jhj_250612	//MAX_STEP_420
			myCh->capa.c_v2 = 0;
			myCh->capa.c_t1 = 0;
			myCh->capa.c_t2 = 0;
			myCh->capa.d_count = 0;
			myCh->capa.d_flag = 0;

			myCh->ccv[1] = myCh->ccv[0];
