				tmp1 = (double)(myCh->misc.cmd_v[0] - myCh->misc.tmpVsens)
					/ (double)myTestCond->local_object[idxStepNo][idx] * 1000.0;

				if(tmp1 > MAX_SUM_ULONG) tmp1 = MAX_SUM_ULONG;	//csk_190718
				val = (long)tmp1;
