				idx = IDX_LOC_OBJ_REF_V2;
				myCh->misc.cmd_v[1] = myTestCond->local_object[idxStepNo][idx];

				idx = IDX_COM_OBJ_ATTRIBUTE_COUNT;
				attr_count = myTestCond->common_object[idx];
