	if(cmd > myPs->config.maxI[rangeI]) {
		cmd = myPs->config.maxI[rangeI];
	} else if(cmd < myPs->config.minI[rangeI]) {
		cmd = myPs->config.minI[rangeI];
	}
	myCh->misc.cmd_i[0] = cmd;

	myCh->misc.cmd_v[0] = myPs->config.maxV[rangeV];
	//ktg_190801s
