		myData->compV[ch] = myCh->op.Vsens;
		if(val < 0) val *= (-1);

		val = (long)((double)val / (double)myPs->config.maxV[i] * 100000.0);
		rtnCode = com_cCodeCheck(ch, C_CD_COM_FAULT_DELTA_V, val);
		if(rtnCode > C_CD_NONE) {
			myCh->op.code = rtnCode;
			myCh->misc.active_division = ACTIVE_DIV_PAUSE;
			return;
		}
