int cUserControl_can_goto(int ch, int rx_idx)
{
	unsigned char tx_flag;
	int tx_idx, i, j, can_ch;
	long val;
	unsigned int dataCount;	//kjh_211021
	S_RT_CAN_MSG can_msg;

	if(myData->CanData[ch][rx_idx].l_val[0] == 0) return -1;
	if(myCh->signal[C_SIG_CMD_GOTO_STEP] != P0) return -2;

	val = (long)myData->CanData[ch][rx_idx].f_val[0] - 1;
	if((val < 1) || (val > myTestCond->common_object[IDX_COM_OBJ_TOTAL_STEP])
		|| ((val - 1) == (long)myCh->op.idxStepNo)) return 1;
	//myCh->misc.user_branch_stepNo = (unsigned char)val; //kjg_w max 300 step
	myCh->misc.user_branch_stepNo = (short int)val; //jhj_250612	//MAX_STEP_420

	myCh->signal[C_SIG_CMD_GOTO_STEP] = P1;
	for(i=0; i < MAX_SLAVE_CH; i++) {
		j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
		if(j >= 0) {
			myData->cData[j].signal[C_SIG_CMD_GOTO_STEP] = P1;
		}
	}

	switch(myPs->config.division_CAN) { //kjh_211021s
		case 1:
			dataCount = myData->canTransmitDataCount[ch][CAN_PORT_MASTER];
			if(dataCount == 0) return -1;
			break;
		default:
			dataCount = myData->canTransmitDataCount[ch][CAN_PORT_MASTER]
				+ myData->canTransmitDataCount[ch][CAN_PORT_SLAVE];
			if(dataCount == 0) return -1;
			break;
	}	//kjh_211021e

	for(tx_idx=0; tx_idx < dataCount; tx_idx++) {	//kjh_211021
	//kjh_211021 for(tx_idx=0; tx_idx < (myData->canTransmitDataCount[ch][0]
	//	+ myData->canTransmitDataCount[ch][1]); tx_idx++) {
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div
			== CAN_TX_FUNC_USER_GOTO) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div2
			== CAN_TX_FUNC_USER_GOTO) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div3
			== CAN_TX_FUNC_USER_GOTO) break;
	}
	if(tx_idx >= dataCount) return -3;	//kjh_211021
	//kjh_211021 if(tx_idx >= (myData->canTransmitDataCount[ch][0]
	//	+ myData->canTransmitDataCount[ch][1])) return -3;

	memset((char *)&can_msg, 0, sizeof(S_RT_CAN_MSG));

	can_msg.id = (unsigned int)myData->canTransmitSetData
		.normalData[ch][tx_idx].canID;
	can_msg.type = 0;
	if(myData->canTransmitSetData.normalData[ch][tx_idx].canType == CAN_TYPE_MASTER)
		i = CAN_TYPE_MASTER;
	else i = CAN_TYPE_SLAVE;
	can_ch = ch * MAX_CAN_TYPE + (i - 1);
	can_msg.length = 3;

	j = myData->canTransmitSetData.normalData[ch][tx_idx].startBit;
	for(i=0; i < 64; i++) {
		if((i >= j) && (i < (j + myData->canTransmitSetData
			.normalData[ch][tx_idx].bitCount))) {
			can_msg.data[i / 8] = (unsigned char)myData->
				CanData[ch][rx_idx].f_val[0]; //kjg_w max step 300
			break;
		}
	}

	for(tx_idx=0; tx_idx < dataCount; tx_idx++) {	//kjh_211021
	//kjh_211021 for(tx_idx=0; tx_idx < (myData->canTransmitDataCount[ch][0]
	//	+ myData->canTransmitDataCount[ch][1]); tx_idx++) {
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div
			== CAN_TX_FUNC_USER_STATE1) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div2
			== CAN_TX_FUNC_USER_STATE1) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div3
			== CAN_TX_FUNC_USER_STATE1) break;
	}
	if(tx_idx >= dataCount) tx_flag = 0;
	//kjh_211021 if(tx_idx >= (myData->canTransmitDataCount[ch][0]
	//	+ myData->canTransmitDataCount[ch][1])) tx_flag = 0;
	else tx_flag = 1;

	if(tx_flag == 1) {
		j = myData->canTransmitSetData.normalData[ch][tx_idx].startBit;
		for(i=0; i < 64; i++) {
			if((i >= j) && (i < (j + myData->canTransmitSetData
				.normalData[ch][tx_idx].bitCount))) {
				if(myCh->op.state == C_RUN) {
					can_msg.data[i / 8] = myCh->op.idxStepNo + 1;
				}
				break;
			}
		}
	}

	rt_can_write(can_ch, (char *)&can_msg);

	return 0;
}

void cSaveCond(int ch)
{
	unsigned char select=0;
	short int idxStepNo;
    int rtn=0, idx, i, j;
	long val, tmp, saveDi=0, recordT;
	unsigned long saveDt, checkDt, minDt;

	checkDt = 0;
	idxStepNo = myCh->op.idxStepNo;
	idx = IDX_LOC_OBJ_SAVE_DELTA_T;
	saveDt = myTestCond->local_object[idxStepNo][idx];
	switch(myData->AppControl.config.systemModel) {
		case C_PNE_450V_250A_10A_115KW:
			minDt = 10; //100ms
			break;
		//kjhw_130429s
		case C_SDI_100V_150A_70A_30KW:
		case C_SDI_100V_150A_70A_30KW_2:
		case C_SDI_100V_150A_70A_30KW_3:
		case C_SDI_100V_150A_70A_30KW_4:
		case C_SDI_100V_150A_70A_30KW_5:
		case C_HLGP_500V_200A_100A_200KW_2:
		case C_HLGP_500V_200A_100A_200KW_3:
	//	case C_HLGP_500V_200A_100A_200KW_4:
		case C_SKE_600V_400A_100A_50A_25A_240KW:
			if(saveDt > 0 && saveDt < 100) {
				if(time_cal_compare(COMP_LESS_THAN_OR_EQUAL_TO,
					myCh->op.runTime_day, myCh->op.runTime,
					0, 360000) > 0) { //1h
				} else {
					saveDt = 100; //1sec
				}
			}
			minDt = 10; //100ms
			break;	//kjhw_130429e
		default:
			minDt = 10; //100ms
			break;
	}

	switch(myData->AppControl.config.systemModel) {
		case C_KATECH_400V_60A_10A_24KW:
		case C_KATECH_450V_150A_10A:
		case C_KATECH_450V_250A_25A_225KW:
		case C_KATECH_450V_250A_25A_225KW_2:
			if(saveDt != 0) {
				tmp = myCh->op.runTime - myCh->misc.saveDt;
				if(tmp >= saveDt) {
					if(myCh->misc.sendDataCount == 0) {
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					} else {
						rtn = 3; //save dT
						select = SAVE_FLAG_SAVING_TIME;
					}
				}
			}
			break;
		case C_TEST_120V_400A_200A_100A_192KW:		//shh_200723
			if(saveDt == 5) { //50ms //kjhw_180325s
				if(myCh->misc.sendDataCount == 0) {
					if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
						myCh->op.runTime, 0, 5) > 0) { //50ms
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					}
				} else {
					if(saveDt != 0) {
						if(myCh->misc.sendDataCount == 1) {
							if(saveDt != 5) saveDt -= 5;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						} else if(myCh->misc.sendDataCount == 2) {
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
							}
						} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
							saveDt = 5;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						}
					}
				}
			} else {
				if(myCh->misc.sendDataCount == 0) {
					if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
						myCh->op.runTime, 0, 10) > 0) { //100ms
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					}
				} else {
					if(saveDt != 0) {
						if(myCh->misc.sendDataCount == 1) {
							if(saveDt != 10) saveDt -= 10;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						} else if(myCh->misc.sendDataCount == 2) {
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
							}
						} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
							saveDt = 10;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						}
					}
				}
			}
			break; //kjhw_180325e
		//jhkw_190830s
		case C_CTP_150V_150A_100A_90KW:	//ktg_191022
			if(saveDt <= 5) { //10ms
				if(myCh->misc.sendDataCount == 0) {
					if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
						myCh->op.runTime, 0, 1) > 0) { //10ms
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					}
				} else {
					if(saveDt != 0) {
						if(myCh->misc.sendDataCount == 1) {
							if(saveDt != 1) saveDt -= 1;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						} else if(myCh->misc.sendDataCount == 2) {
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
							}
						} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
							saveDt = 1;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						}
					}
				}
			} else {
				if(myCh->misc.sendDataCount == 0) {
					if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
						myCh->op.runTime, 0, 10) > 0) { //100ms
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					}
				} else {
					if(saveDt != 0) {
						if(myCh->misc.sendDataCount == 1) {
							if(saveDt != 10) saveDt -= 10;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						} else if(myCh->misc.sendDataCount == 2) {
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
							}
						} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
							saveDt = 10;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						}
					}
				}
			}
			break;	//jhkw_190830e
		default: //kjg_110525
			if(myCh->misc.sendDataCount == 0) {
				if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
					myCh->op.runTime, 0, 10) > 0) { //100ms
					rtn = 2; //save time(start)
					select = SAVE_FLAG_SAVING_TIME;
				}
			} else {
				if(saveDt != 0) {
					if(myCh->misc.sendDataCount == 1) {
						if(saveDt != 10) saveDt -= 10;
						tmp = myCh->op.runTime - myCh->misc.saveDt;
						if(tmp >= saveDt) {
							rtn = 3; //save dT
							select = SAVE_FLAG_SAVING_TIME;
							myCh->misc.sendDataCount = 2;
						}
					} else if(myCh->misc.sendDataCount == 2) {
						tmp = myCh->op.runTime - myCh->misc.saveDt;
						if(tmp >= saveDt) {
							rtn = 3; //save dT
							select = SAVE_FLAG_SAVING_TIME;
						}
					} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
						saveDt = 10;
						tmp = myCh->op.runTime - myCh->misc.saveDt;
						if(tmp >= saveDt) {
							rtn = 3; //save dT
							select = SAVE_FLAG_SAVING_TIME;
							myCh->misc.sendDataCount = 2;
						}
					}
				}
			}
			break;
	}

	tmp = myCh->op.runTime - myCh->misc.saveDt;
	if((rtn == 0) && (tmp >= minDt)) {
		idx = IDX_LOC_OBJ_SAVE_DELTA_V;
		val = myTestCond->local_object[idxStepNo][idx];
		if(val != 0) {
   	   		tmp = myCh->op.Vsens - myCh->misc.saveDv;
			if(tmp > 0) {
				if(tmp >= val) {
					rtn = 4; //save dV
					select = SAVE_FLAG_SAVING_DELTA_V;
				}
			} else if(tmp < 0) {
				if(tmp * (-1) >= val) {
					rtn = 4; //save dV
					select = SAVE_FLAG_SAVING_DELTA_V;
				}
			}
		}
	}

	tmp = myCh->op.runTime - myCh->misc.saveDt;
	if((rtn == 0) && (tmp >= minDt)
		&& (myData->ChAttribute[ch].chNo_master != 0)) {
		if(myData->ChAttribute[ch].opType != OP_INDEPENDENT) {
			saveDi = myCh->op.Isens;
			for(i=0; i < MAX_SLAVE_CH; i++) {
				j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
				if(j >= 0) {
					saveDi += myData->cData[j].op.Isens;
				}
			}
		} else {
			saveDi = myCh->op.Isens;
		}
		idx = IDX_LOC_OBJ_SAVE_DELTA_I;
		val = myTestCond->local_object[idxStepNo][idx];
		if(val != 0) {
   	   		tmp = saveDi - myCh->misc.saveDi;
			if(tmp > 0) {
				if(tmp >= val) {
					rtn = 5; //save dI
					select = SAVE_FLAG_SAVING_DELTA_I;
				}
			} else if(tmp < 0) {
				if(tmp * (-1) >= val) {
					rtn = 5; //save dI
					select = SAVE_FLAG_SAVING_DELTA_I;
				}
			}
		}
	}

	tmp = myCh->op.runTime - myCh->misc.saveDt;
	if((rtn == 0) && (tmp >= minDt)) {
		idx = IDX_LOC_OBJ_SAVE_DELTA_TEMP;
		val = myTestCond->local_object[idxStepNo][idx];
		if(val != 0) {
   	   		tmp = myCh->op.temp - myCh->misc.saveDtemp;
			if(tmp > 0) {
				if(tmp >= val) {
					rtn = 6; //save dTemp
					select = SAVE_FLAG_SAVING_DELTA_TEMP;
				}
			} else if(tmp < 0) {
				if(tmp * (-1) >= val) {
					rtn = 6; //save dTemp
					select = SAVE_FLAG_SAVING_DELTA_TEMP;
				}
			}
		}
	}

	if(rtn == 2) { //save(start)
		myCh->op.select = select;
		myCh->misc.saveDt = myCh->op.runTime;
   	   	myCh->misc.saveDv = myCh->op.Vsens;
   	  	myCh->misc.saveDi = saveDi;
   	   	myCh->misc.saveDtemp = myCh->op.temp;
		myCh->misc.sendDataCount = 1;
		myCh->misc.saveCode = myCh->op.code;
		send_save_msg(ch);
	} else if(rtn > 2) { //save
		myCh->op.select = select;
		myCh->misc.saveDt = myCh->op.runTime;
   	   	myCh->misc.saveDv = myCh->op.Vsens;
   	  	myCh->misc.saveDi = saveDi;
   	   	myCh->misc.saveDtemp = myCh->op.temp;
		myCh->misc.saveCode = myCh->op.code;
		send_save_msg(ch);
	}

	idx = IDX_LOC_OBJ_SAVE_RECORD_T1;
	recordT = myTestCond->local_object[idxStepNo][idx];
	if(recordT != 0 && recordT == myCh->op.runTime) send_record_msg(ch, 1);

	idx = IDX_LOC_OBJ_SAVE_RECORD_T2;
	recordT = myTestCond->local_object[idxStepNo][idx];
	if(recordT != 0 && recordT == myCh->op.runTime) send_record_msg(ch, 2);

	idx = IDX_LOC_OBJ_SAVE_RECORD_T3;
	recordT = myTestCond->local_object[idxStepNo][idx];
	if(recordT != 0 && recordT == myCh->op.runTime) send_record_msg(ch, 3);

	idx = IDX_LOC_OBJ_SAVE_RECORD_T4;
	recordT = myTestCond->local_object[idxStepNo][idx];
	if(recordT != 0 && recordT == myCh->op.runTime) send_record_msg(ch, 4);

	idx = IDX_LOC_OBJ_SAVE_RECORD_T5;
	recordT = myTestCond->local_object[idxStepNo][idx];
	if(recordT != 0 && recordT == myCh->op.runTime) send_record_msg(ch, 5);
}

void cSoftFeedback(int ch)
{
	S_USER_DEFINE_MODE user_mode;
	short int idxStepNo;

	if(myCh->signal[C_SIG_SOFT_FEEDBACK_DELAY] != 0) { //kjg_170810
		myCh->signal[C_SIG_SOFT_FEEDBACK_DELAY]--;
		return;
	}

	idxStepNo = myCh->op.idxStepNo;

	switch(myData->AppControl.config.systemModel) {
		case C_KATECH_20V_1000A_500A_100A: //csk_120312
		case C_LGC_50V_40A_10A_4A: //csk_120206
		case C_LGC_50V_40A_10A_4A_2:
		case C_LGC_50V_40A_10A_4A_3:
		case C_LGC_50V_40A_10A_4A_4:
		case C_SDI_70V_50A_5A_4KW:
		case C_SDI_70V_50A_5A_4KW_2:
		case C_SDI_70V_50A_5A_7KW:
		case C_SDI_70V_50A_5A_7KW_2:
		case C_SDI_70V_250A_25A_18KW:
			switch(myCh->op.stepType) {
				case STEP_EXTERNAL_CAN:
					cSoftFeedback_C3(ch);
					break;
				case STEP_PATTERN:
					cSoftFeedback_C2(ch);
					break;
				default:
					cSoftFeedback_C1(ch);
					break;
			}
			break;
		default:
			switch(myCh->op.stepType) {
				case STEP_EXTERNAL_CAN_2: //kjg_140916
					cSoftFeedback_A5(ch);
					break;
				case STEP_USERMAP: //kjhw_140826
					cSoftFeedback_A4(ch);
					break;
				case STEP_EXTERNAL_CAN:
					cSoftFeedback_A3(ch);
					break;
				case STEP_PATTERN:
					cSoftFeedback_A2(ch);
					break;
				case STEP_CHARGE:
//20181219 KHK----------------------------------------
					user_mode = cFind_User_Define_Mode(ch);
					if(user_mode.org_mode == MODE_USER) {
						if(user_mode.mode == MODE_CC_CV
							|| user_mode.mode == MODE_CV) {
							cSoftFeedback_Charge_SOC_Tracking(ch);
						} else {
							cSoftFeedback_A1(ch);
						}
					} else {
						if(myTestCond->local_object[idxStepNo][IDX_LOC_OBJ_SOC_TRACKING_FLAG]
							== P0 || myCh->op.stepMode == MODE_CP) {
							if(myTestCond->local_object[idxStepNo][IDX_LOC_OBJ_SEQUENCE_CHARGE_FLAG] == P1) {
								cSoftFeedback_Charge_SOC_Tracking(ch);
							} else {
								cSoftFeedback_A1(ch);
							}

						} else {
							cSoftFeedback_Charge_SOC_Tracking(ch);
						}
					}
//----------------------------------------------------
					break;
				default:
					cSoftFeedback_A1(ch);
					break;
			}
			break;
	}
}

void cSoftFeedback_Charge_SOC_Tracking(int ch)
{
	short int scan_ch, idxStepNo;
	int group;
	long val1, val2, val3, check_t1, check_t2, check_t2a, check_t3, check_t3a;
	//long val; //kjh_160623
	double v_cmp_p, v_cmp_n, i_cmp_p, i_cmp_n, p_cmp_p, p_cmp_n, tmp1, tmp2;
	double v_cmp_p2, v_cmp_n2;

	switch(myData->AppControl.config.systemModel) {
		default:
			if(ch < myPs->config.chInGroup[0]) group = 0;
			else group = 1;
			break;
	}

	myGroup = &(myData->gData[group]);

	if(ch == 0) scan_ch = myGroup->misc.scan_ch[ch];
	else scan_ch = myGroup->misc.scan_ch[ch] + 12;

    idxStepNo = myCh->op.idxStepNo;

	val2 = myCh->misc.cmd_i[0];

	switch(myCh->op.stepType) {
		case STEP_CHARGE:
			val1 = myCh->misc.cmd_v[0];
			break;
		case STEP_DISCHARGE:
		case STEP_Z:
			val1 = myCh->misc.cmd_v[1];
			break;
		case STEP_PATTERN: //kjhw_140106
			if(val2 >= 0) val1 = myCh->misc.cmd_v[0]; //charge
			else val1 = myCh->misc.cmd_v[1]; //discharge
			break;
		default:
			val1 = myCh->misc.cmd_v[0];
			break;
	}
	v_cmp_p = (double)myPs->config.maxV[myCh->op.rangeV] * 0.002;
	v_cmp_n = v_cmp_p * (-1.0);
	v_cmp_p2 = (double)myPs->config.maxV[myCh->op.rangeV] * 0.0001;
	v_cmp_n2 = v_cmp_p2 * (-1.0);
	i_cmp_p = (double)myPs->config.maxI[myCh->op.rangeI] * 0.05;
	i_cmp_n = i_cmp_p * (-1.0);

	//p_cmp_p = (double)val3 * 2.0;
	p_cmp_p = (double)val3 * 0.15; //kjhw_150616
	p_cmp_n = p_cmp_p * (-1.0);

	switch(myData->AppControl.config.systemModel) { //kjhw_180325
		default:
			check_t1 = 0; //30ms kjg_100520
			check_t2 = 5; //50ms
			check_t2a = 100 * (long)myPs->misc.increment_period; //10ms
			check_t3 = 90 * (long)myPs->misc.increment_period; //90ms
			check_t3a = 100 * (long)myPs->misc.increment_period; //20ms
			break;
	}
	switch(myCh->op.stepType) {
		case STEP_CHARGE:
			if(myPs->config.soft_feedback1[2] == 0) return;
			if(myCh->misc.cv_select != P0) return; //kjg_121022
			if(myCh->op.stepMode == MODE_CC
				|| myCh->op.stepMode == MODE_CV
				|| myCh->op.stepMode == MODE_CC_CV) {
				tmp1 = (double)val1 - (double)myCh->misc.tmpVsens;
				tmp2 = (double)val2 - (double)myCh->misc.tmpIsens;
				//if(tmp1 > v_cmp_p) { //CC Area
					if(myPs->config.soft_feedback1[1] == 0) return;
					if(myCh->misc.cv_select != P0) return; //kjg_121022
					myCh->misc.fbCountI++;
					if((myCh->misc.fbCountI * myPs->config.scan_period)
						>= check_t2a) {
						myCh->misc.fbCountV = 0;
						myCh->misc.fbCountI = 0;
						cCalCmdI(ch, val2, 0, myCh->op.rangeI);
					}
				//}
			}
			break;
		default: break;
	}
}
