				//tmp_f = tmp_f * 1000000.0;					//csk_191018
				tmp_f = tmp_f * myData->mData.patt_ratioI;	//kjh_220321

				tmp_l = (long)tmp_f / attr_count;				//csk_191018
				if(val2 >= 0) {
					if(val2 > tmp_l) val2a = tmp_l;				//csk_191018
				} else {
					if((val2 * (-1)) > tmp_l) val2a = (tmp_l * (-1));	//csk_191018
				}
