void cCalculate_CV_CC_Time(int ch)
{
	long val1, val2;
	float v_cmp, i_cmp, tmp1, tmp2;
	int i, j; //kjhw_130408

	myData->cData[ch].op.cv_flag = 0;

	tmp1 = (float)myCh->op.Vsens;
	if(tmp1 < 0) tmp1 *= (-1.0);

	tmp2 = (float)myCh->op.Isens;
#ifdef __B_TYPE__
	if(myCh->op.stepType ==  STEP_CHARGE) { //kjhw_130408
	} else {
		tmp2 *= (-1.0);
	}
#else
	if(tmp2 < 0) tmp2 *= (-1.0);
#endif
	v_cmp = (float)myPs->config.maxV[myCh->op.rangeV] * 0.002;
	//i_cmp = (float)myPs->config.maxI[myCh->op.rangeI] * 0.005;
	i_cmp = (float)myPs->config.maxI[myCh->op.rangeI] * 0.002;	//ksh_250203

	val2 = myCh->misc.cmd_i[0];
	if(val2 < 0) val2 *= (-1);

	if(myCh->misc.cmd_i[0] >= 0) {
		val1 = myCh->misc.cmd_v[0];
	} else {
		val1 = myCh->misc.cmd_v[1];
	}

	if(tmp1 >= ((float)val1 - v_cmp) && tmp1 <= ((float)val1 + v_cmp)) {
		if(tmp2 <= ((float)val2 - i_cmp)) {
			//COA_VER_100B2~
			myData->cData[ch].op.cv_flag = 1;
			
			time_cal_increment(myCh->op.cvTime_day, myCh->op.cvTime,
				myPs->misc.increment_period);
			myCh->op.cvTime_day = myPs->misc.tmp_inc_time_day;
			myCh->op.cvTime = myPs->misc.tmp_inc_time;
		}
	}

	myCh->op.ccTime_day = myCh->op.runTime_day - myCh->op.cvTime_day;
	myCh->op.ccTime = myCh->op.runTime - myCh->op.cvTime;

	//kjhw_130408s
	if((myData->ChAttribute[ch].chNo_master != 0)
		&& (myData->ChAttribute[ch].opType != OP_INDEPENDENT)) {
		for(i=0; i < MAX_SLAVE_CH; i++) {
			j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
			if(j >= 0) {
				if((myCh->op.cvTime_day < myData->cData[j].op.cvTime_day)
					|| (myCh->op.cvTime < myData->cData[j].op.cvTime)) {
					myCh->op.cvTime_day = myData->cData[j].op.cvTime_day;
					myCh->op.cvTime = myData->cData[j].op.cvTime;
					myCh->op.ccTime_day = myData->cData[j].op.ccTime_day;
					myCh->op.ccTime = myData->cData[j].op.ccTime;
				}
			}
		}
	}
	//kjhw_130408e
}

int	cCodeCompare(int ch, int code, int compType, long val1_a, long val1_b)
{
	int rtn;

	rtn = C_CD_NONE;

	switch(compType) {
		case COMP_NONE:
			rtn = 0;
			break;
		case COMP_LESS_THAN:	//val1_a < val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a < val1_b) rtn = 1;
				else rtn = -1;
			}
			break;
		case COMP_LESS_THAN_OR_EQUAL_TO: //val1_a <= val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a <= val1_b) rtn = 2;
				else rtn = -1;
			}
			break;
		case COMP_GREATER_THAN: //val1_a > val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a > val1_b) rtn = 3;
				else rtn = -1;
			}
			break;
		case COMP_GREATER_THAN_OR_EQUAL_TO: //val1_a >= val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a >= val1_b) rtn = 4;
				else rtn = -1;
			}
			break;
		case COMP_EQUAL_TO: //val1_a = val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a == val1_b) rtn = 5;
				else rtn = -1;
			}
			break;
		case COMP_NOT_EQUAL_TO: //val1_a != val1_b
			rtn = 0;
			break;
		default:
			rtn = 0;
			break;
	}
	if(rtn < 0) return 0;

	return code;
}

int	cCodeCompare2(int ch, int code, char type[4], long val1_a, long val1_b)
{
	char compType[4];
	int rtn;

	rtn = C_CD_NONE;

	memset(compType, 0, sizeof compType);
	strcpy(compType, type);
	if(strcmp(compType, "N") == 0) {
		rtn = 0;
	} else if(strcmp(compType, "<") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a < val1_b) rtn = 1;
			else rtn = -1;
		}
	} else if(strcmp(compType, "<=") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a <= val1_b) rtn = 2;
			else rtn = -1;
		}
	} else if(strcmp(compType, ">") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a > val1_b) rtn = 3;
			else rtn = -1;
		}
	} else if(strcmp(compType, ">=") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a >= val1_b) rtn = 4;
			else rtn = -1;
		}
	} else if(strcmp(compType, "=") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a == val1_b) rtn = 5;
			else rtn = -1;
		}
	} else if(strcmp(compType, "==") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a == val1_b) rtn = 5;
			else rtn = -1;
		}
	} else if(strcmp(compType, "!=") == 0) {
		if(val1_b == 0) {
			rtn = -1;
		} else {
			if(val1_a == val1_b) rtn = 6;
			else rtn = -1;
		}
	} else {
		rtn = 0;
	}

	if(rtn < 0) return 0;

	return code;
}

