//khj_201120
int	loc_cCodeCheck_can(int ch, int code, long val1_a, long factor, int can_idx, unsigned char i)
{
	short int idxStepNo;
	unsigned long count;
	int idx1, rtn, idx;
	short int func_div;
	double temp_val_d;	//kjh_220915
	long val1_b;

	idxStepNo = myCh->op.idxStepNo;

	rtn = C_CD_NONE;
	code -= C_CD_END_START;
	
	if(myTestCond->local_chCode[idxStepNo][code].check_delay_count != 0) {
		myTestCond->local_chCode[idxStepNo][code].check_delay_count--;
		return rtn;
	}

	count = (unsigned long)myTestCond->local_chCode[idxStepNo][code]
		.compCount;
	if(count == 0) return rtn;

	idx1 = (int)myTestCond->local_chCode[idxStepNo][code].compIndex1;
	val1_b = myTestCond->local_object[idxStepNo][idx1] * factor;
	
	//kjh_220915s
	idx = IDX_LOC_OBJ_CAN_FUNC_DIV_1 + i;
	func_div = (int)myTestCond->local_object[idxStepNo][idx];
	if(func_div == CAN_RX_FUNC_DIV_VALUE_RATIO) {
		temp_val_d = ((double)val1_a * (double)val1_b / 100000.0) ;
		if(temp_val_d < 0) {
			temp_val_d *= (-1);
		}
		if(temp_val_d > MAX_SUM_ULONG) temp_val_d = MAX_SUM_ULONG;
			val1_b = (long)temp_val_d;
		if(val1_b < 0) {
			val1_b *= (-1);
		}
		val1_a = myData->cData[ch].misc.sum_AmpareHour;
		if(val1_a < 0) {
			val1_a *= (-1);
		}
	}	//val1_a == CAN * rate , val1_b == sum_AmapreHour
	//kjh_220915e
	switch(myTestCond->local_chCode[idxStepNo][code].compType) {
		case COMP_NONE:
			rtn = 0;
			break;
		case COMP_LESS_THAN: //val1_a < val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a < val1_b) rtn = 1;
				else rtn = -1;
			}
			break;
		case COMP_LESS_THAN_OR_EQUAL_TO: //val1_a <= val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a <= val1_b) rtn = 2;
				else rtn = -1;
			}
			break;
		case COMP_GREATER_THAN: //val1_a > val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a > val1_b) rtn = 3;
				else rtn = -1;
			}
			break;
		case COMP_GREATER_THAN_OR_EQUAL_TO: //val1_a >= val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a >= val1_b) rtn = 4;
				else rtn = -1;
			}
			break;
		case COMP_EQUAL_TO: //val1_a = val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a == val1_b) rtn = 5;
				else rtn = -1;
			}
			break;
		case COMP_NOT_EQUAL_TO: //val1_a != val1_b
			rtn = 0;
			break;
		default:
			rtn = 0;
			break;
	}

	
	if(rtn < 0) {
		myData->can_check[ch][can_idx][code] = 0;
		return 0;
	}
	
	if(rtn > 0) {					//khj_201208s
		if(myData->can_check[ch][can_idx][code] == 0) {
			time_cal_increment(myCh->op.runTime_day, myCh->op.runTime, count);
			myData->local_codeCount_can_day[ch][can_idx][i] = myPs->misc.tmp_inc_time_day;
			myData->local_codeCount_can_time[ch][can_idx][i] = myPs->misc.tmp_inc_time;
			myData->can_check[ch][can_idx][code] = 1;
		}
	}

	if(time_cal_compare(COMP_LESS_THAN_OR_EQUAL_TO,
		myData->local_codeCount_can_day[ch][can_idx][i],  
		myData->local_codeCount_can_time[ch][can_idx][i], 
		myCh->op.runTime_day,myCh->op.runTime) > 0) {
		rtn = code + C_CD_END_START;
		myData->local_codeCount_can_day[ch][can_idx][i] = 0; 
		myData->local_codeCount_can_time[ch][can_idx][i] = 0;
		
		memset((char *)&myData->can_check[ch][0][0], 0, 
			sizeof(unsigned char) * MAX_CAN_DATA * MAX_LOC_CODE);

	} else {
		rtn = C_CD_NONE;
	}
	return rtn;						//khj_201208e
	
/*	myCh->misc.local_codeCount[code]++; 
	myData->local_codeCount_can[ch][can_idx][i]++; 
	if(myData->local_codeCount_can[ch][can_idx][i] >= count) { 
		rtn = code + C_CD_END_START;
	}
	return rtn;*/

}

