int out_mux_select(int ch)
{	//kjhw_160106s
	unsigned char flag1, flag2, flag3, flag4;
	int group;
	unsigned long tmpDelayCount;

	group = 0;
	//kjh_211021 tmpDelayCount = 200; //2000msec
	tmpDelayCount = 2000; //2000msec

	flag1 = Read_InPoint(group, ch+1, I_MUX_A_P);
	flag2 = Read_InPoint(group, ch+1, I_MUX_A_N);
	flag3 = Read_InPoint(group, ch+1, I_MUX_B_P);
	flag4 = Read_InPoint(group, ch+1, I_MUX_B_N);

	switch(myCh->signal[C_SIG_OUT_MUX_SELECT]) {
		case P0:
			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_OUT_MUX_SELECT]++;
			break;
		case P1:
			switch(myCh->misc.out_mux) {
				case 0: //all_off
					if(myCh->misc.out_mux_backup == 0) {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P10;
						break;
					}
					if(myCh->misc.out_mux_backup == 1) { //mux_a
						if((flag1 == ON) && (flag2 == ON)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							Select_OutPoint(group, ch+1, O_MUX_A_P, OFF);
							Select_OutPoint(group, ch+1, O_MUX_A_N, OFF);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					} else { //mux_b
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == ON) && (flag4 == ON)) {
							Select_OutPoint(group, ch+1, O_MUX_B_P, OFF);
							Select_OutPoint(group, ch+1, O_MUX_B_N, OFF);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					}
					break;
				case 1: //mux_a
					if(myCh->misc.out_mux_backup == 1) {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P10;
						break;
					}
					if(myCh->misc.out_mux_backup == 0) { //all_off
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							Select_OutPoint(group, ch+1, O_MUX_A_P, ON);
							Select_OutPoint(group, ch+1, O_MUX_A_N, ON);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					} else { //mux_b
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == ON) && (flag4 == ON)) {
							Select_OutPoint(group, ch+1, O_MUX_B_P, OFF);
							Select_OutPoint(group, ch+1, O_MUX_B_N, OFF);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					}
					break;
				case 2: //mux_b
					if(myCh->misc.out_mux_backup == 2) {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P10;
						break;
					}
					if(myCh->misc.out_mux_backup == 0) { //all_off
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							Select_OutPoint(group, ch+1, O_MUX_B_P, ON);
							Select_OutPoint(group, ch+1, O_MUX_B_N, ON);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					} else { //mux_a
						if((flag1 == ON) && (flag2 == ON)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							Select_OutPoint(group, ch+1, O_MUX_A_P, OFF);
							Select_OutPoint(group, ch+1, O_MUX_A_N, OFF);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					}
					break;
				default: break;
			}
			break;
		case P2:
			myCh->misc.tmpDelayTime++;
			//kjh_211021 if(myCh->misc.tmpDelayTime < tmpDelayCount) break;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period)
				< tmpDelayCount) break;	//kjh_211021
			myCh->misc.tmpDelayTime = 0;
			myCh->misc.out_mux_fault = myCh->signal[C_SIG_OUT_MUX_SELECT];
			switch(myCh->misc.out_mux) {
				case 0: //all_off
					if((flag1 == OFF) && (flag2 == OFF)
						&& (flag3 == OFF) && (flag4 == OFF)) {
						myCh->signal[C_SIG_OUT_MUX_SELECT]++;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				case 1: //mux_a
					if(myCh->misc.out_mux_backup == 0) { //all_off
						if((flag1 == ON) && (flag2 == ON)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					} else { //mux_b
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							Select_OutPoint(group, ch+1, O_MUX_A_P, ON);
							Select_OutPoint(group, ch+1, O_MUX_A_N, ON);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					}
					break;
				case 2: //mux_b
					if(myCh->misc.out_mux_backup == 0) { //all_off
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == ON) && (flag4 == ON)) {
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					} else { //mux_a
						if((flag1 == OFF) && (flag2 == OFF)
							&& (flag3 == OFF) && (flag4 == OFF)) {
							Select_OutPoint(group, ch+1, O_MUX_B_P, ON);
							Select_OutPoint(group, ch+1, O_MUX_B_N, ON);
							myCh->signal[C_SIG_OUT_MUX_SELECT]++;
						} else {
							myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
						}
					}
					break;
				default: break;
			}
			break;
		case P3:
			myCh->misc.tmpDelayTime++;
			//kjh_211021 if(myCh->misc.tmpDelayTime < tmpDelayCount) break;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period)
				< tmpDelayCount) break;	//kjh_211021
			myCh->misc.tmpDelayTime = 0;
			myCh->misc.out_mux_fault = myCh->signal[C_SIG_OUT_MUX_SELECT];
			switch(myCh->misc.out_mux) {
				case 0: //all_off
					if((flag1 == OFF) && (flag2 == OFF)
						&& (flag3 == OFF) && (flag4 == OFF)) {
						myCh->signal[C_SIG_OUT_MUX_SELECT]++;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				case 1: //mux_a
					if((flag1 == ON) && (flag2 == ON)
						&& (flag3 == OFF) && (flag4 == OFF)) {
						myCh->signal[C_SIG_OUT_MUX_SELECT]++;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				case 2: //mux_b
					if((flag1 == OFF) && (flag2 == OFF)
						&& (flag3 == ON) && (flag4 == ON)) {
						myCh->signal[C_SIG_OUT_MUX_SELECT]++;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				default: break;
			}
			break;
		case P10:
			myCh->misc.tmpDelayTime++;
			//kjh_211021 if(myCh->misc.tmpDelayTime < tmpDelayCount) break;
			if((myCh->misc.tmpDelayTime * myPs->config.scan_period)
				< tmpDelayCount) break;	//kjh_211021
			myCh->misc.tmpDelayTime = 0;
			myCh->misc.out_mux_fault = myCh->signal[C_SIG_OUT_MUX_SELECT];
			switch(myCh->misc.out_mux) {
				case 0: //all_off
					if(flag1 == OFF && flag2 == OFF
						&& flag3 == OFF && flag4 == OFF) {
						myCh->misc.out_mux_backup = 0;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				case 1: //mux_a
					if(flag1 == ON && flag2 == ON
						&& flag3 == OFF && flag4 == OFF) {
						myCh->misc.out_mux_backup = 1;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				case 2: //mux_b
					if(flag1 == OFF && flag2 == OFF
						&& flag3 == ON && flag4 == ON) {
						myCh->misc.out_mux_backup = 2;
					} else {
						myCh->signal[C_SIG_OUT_MUX_SELECT] = P200;
					}
					break;
				default: break;
			}

			myCh->signal[C_SIG_OUT_MUX_SELECT] = P100;
			break;
		case P100: break;
		case P200:
			Select_OutPoint(group, ch+1, O_MUX_A_P, OFF);
			Select_OutPoint(group, ch+1, O_MUX_A_N, OFF);
			Select_OutPoint(group, ch+1, O_MUX_B_P, OFF);
			Select_OutPoint(group, ch+1, O_MUX_B_N, OFF);

			myCh->signal[C_SIG_OUT_MUX_SELECT] = P0;
			break;
		default:
			myCh->signal[C_SIG_OUT_MUX_SELECT]++;
			break;
	}
	return myCh->signal[C_SIG_OUT_MUX_SELECT];
}	//kjhw_160106e

