//shhw_220919s
int cc_deltaV_check(int ch) 
{
	short int idxStepNo;	
	int idx, rtnCode;	
	long val;	
	unsigned long time_period, run_time;
	
	idxStepNo = myCh->op.idxStepNo;
	run_time = myCh->op.runTime;

	if(myCh->op.runTime <= 100) {
		idx = IDX_LOC_OBJ_FAULT_CC_DELTA_V_TIME_INIT;
		myCh->misc.time_init2 = myTestCond->local_object[idxStepNo][idx];
	}
   	//before 1s, it initializes myCh->misc.time_init2's value
	
	idx = IDX_LOC_OBJ_FAULT_CC_DELTA_V_TIME_PERIOD;
	time_period = myTestCond->local_object[idxStepNo][idx];
	
	if(myCh->misc.time_init2 == run_time) {
		myCh->misc.time_check2 = run_time + time_period;
		myCh->misc.preV2 = myCh->op.Vsens;

	} else if(myCh->misc.time_check2 == run_time) {
		val = myCh->op.Vsens - myCh->misc.preV2;
		if(val < 0) val = val * (-1);
		
		myCh->misc.time_check2 += time_period;		

		rtnCode = loc_cCodeCheck(ch, C_CD_FAULT_CC_DELTA_V_ERROR,val, 1);
		return rtnCode;
	}
		return 0;
}
